export const getUpdateTopicUrl = (id: number | string,) => {




  return `/api/topics/${id}`
}

export const updateTopic = async (id: number | string,
    updateTopicRequest: UpdateTopicRequest, options?: Parameters<typeof apiFetch>[1]): Promise<TopicResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<TopicResponse>(getUpdateTopicUrl(id),
  {
    ...options,
    method: 'PUT',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(updateTopicRequest)
  }
);}





export const getUpdateTopicMutationKey = () => ['updateTopic'] as const;

export const getUpdateTopicMutationOptions = <TError = ErrorType<ValidationProblemDetails | ProblemDetails>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateTopic>>, TError,UpdateTopicMutationVariables, TContext>, request?: SecondParameter<typeof apiFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof updateTopic>>, TError,UpdateTopicMutationVariables, TContext> => {

const mutationKey = getUpdateTopicMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof updateTopic>>, UpdateTopicMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  updateTopic(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UpdateTopicMutationResult = NonNullable<Awaited<ReturnType<typeof updateTopic>>>
    export type UpdateTopicMutationBody = UpdateTopicRequest
    export type UpdateTopicMutationError = ErrorType<ValidationProblemDetails | ProblemDetails>
    export type UpdateTopicMutationVariables = {id: number | string;data: UpdateTopicRequest}

    export const useUpdateTopic = <TError = ErrorType<ValidationProblemDetails | ProblemDetails>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof updateTopic>>, TError,UpdateTopicMutationVariables, TContext>, request?: SecondParameter<typeof apiFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof updateTopic>>,
        TError,
        UpdateTopicMutationVariables,
        TContext
      > => {
      return useMutation(getUpdateTopicMutationOptions(options), queryClient);
    }

